const { fornecedor_id, valor, categoria } = $input.first().body;

return {
  fornecedor_id,
  valor,
  categoria,
  timestamp: new Date().toISOString(),
  historico_fornecedor: fornecedor_id === 1 ? '5+ compras anteriores, taxa 98% sucesso' : 'Fornecedor novo'
};

