Valor: R$ {{ $node["Preparar Dados"].output.first().json.valor }}
Categoria: {{ $node["Preparar Dados"].output.first().json.categoria }}
Histórico: {{ $node["Preparar Dados"].output.first().json.historico_fornecedor }}

